use crate::{mswm02 as m,catalog,model::*,rules::*,unit_support::*};
use crate::jc029_tests::pass_top;
fn setup()->Game{let mut g=game();g.players[0].society_zone.card=Some(g.make_card(m::ID,0));fund(&mut g,0,"JC125",4);g}
fn clear(g:&Game,seat:usize,mode:&str)->Action{Action{card_id:Some(g.players[0].society_zone.card.as_ref().unwrap().id.clone()),ability_id:Some(m::CLEAR.into()),option:Some(mode.into()),target_id:Some(format!("society:p{seat}")),..Action::new("activate")}}
fn media()->String{catalog::catalog().cards.iter().find(|c|c.supported&&c.subtypes.iter().any(|s|matches!(s.as_str(),"媒体"|"互联网"))&&c.cost>0).unwrap().id.clone()}
fn contest(g:&Game,id:String)->Action{Action{card_id:Some(g.players[0].society_zone.card.as_ref().unwrap().id.clone()),ability_id:Some(m::CONTEST.into()),cost_selected:Some(vec![id]),..Action::new("activate")}}
#[test]
fn mswm02_original_gray_six_and_printed_construction_closed(){let s=crate::society::definition(m::ID).unwrap();assert_eq!(s.card.color,"灰");assert_eq!(s.starting_hand,6);assert!(!s.card.supported);for c in &catalog::catalog().cards{let expected=matches!(c.color.as_str(),"灰"|"黄"|"中立")||c.subtypes.iter().any(|s|matches!(s.as_str(),"特工"|"媒体"|"互联网"));assert_eq!(crate::society::validate_construction(s,&[catalog::DeckEntry{card_id:c.id.clone(),count:1}],&catalog::catalog().cards).is_ok(),expected,"{}",c.id);}}
#[test]
fn mswm02_clear_any_society_one_kind_and_once_shared_between_modes(){for seat in 0..4{for mode in ["exposure","secrecy"]{let mut g=setup();if mode=="exposure"{g.players[seat].society_zone.exposure=3;}else{g.players[seat].society_zone.secrecy=4;}let a=clear(&g,seat,mode);act(&mut g,0,a);assert!(g.players[0].society_zone.used_once_per_game.contains(m::CLEAR));pass_top(&mut g);assert_eq!((g.players[seat].society_zone.exposure,g.players[seat].society_zone.secrecy),(0,0));g.players[0].society_zone.card.as_mut().unwrap().exhausted=false;let a=clear(&g,seat,if mode=="exposure"{"secrecy"}else{"exposure"});reject(&mut g,0,a);restore(&mut g);}}}
#[test]
fn mswm02_clear_reads_resolution_count_and_target_elimination_keeps_usage(){let mut g=setup();g.players[2].society_zone.exposure=1;let a=clear(&g,2,"exposure");act(&mut g,0,a);g.players[2].society_zone.exposure=4;pass_top(&mut g);assert_eq!(g.players[2].society_zone.exposure,0);let mut g=setup();let a=clear(&g,2,"secrecy");act(&mut g,0,a);g.eliminate(2);restore(&mut g);pass_top(&mut g);assert!(g.players[0].society_zone.used_once_per_game.contains(m::CLEAR));}
#[test]
fn mswm02_discard_cost_is_qualified_atomic_and_bonus_frozen_printed_cost(){let mut g=setup();let wrong=held(&mut g,"JC125",0);let a=contest(&g,wrong);reject(&mut g,0,a);let def=media();let cost=catalog::card(&def).cost;let id=held(&mut g,&def,0);for seat in 0..4{held(&mut g,"JC125",seat);deck_cards(&mut g,seat,&["JC125";4]);}let a=contest(&g,id.clone());act(&mut g,0,a);assert!(!g.players[0].hand.iter().any(|c|c.id==id));assert_eq!(g.resources(0),2);assert_eq!(g.players[0].graveyard.last().unwrap().definition,def);pass_top(&mut g);assert_eq!(g.mystic_contest.as_ref().unwrap().bonuses[0].amount,cost);restore(&mut g);
 let mut bad=g.clone();bad.mystic_contest.as_mut().unwrap().bonuses[0].amount+=1;assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());let mut bad=g.clone();bad.mystic_contest.as_mut().unwrap().bonuses.clear();assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());
 for _ in 0..64{if g.pending.is_some(){resolve_choice(&mut g);}else if !g.stack.is_empty(){pass_top(&mut g);}else{break;}}assert!(g.pending.is_none()&&g.mystic_contest.is_none());assert_eq!(g.mystic_history.len(),1);assert_eq!(g.mystic_history[0].bonuses[0].amount,cost);restore(&mut g);let mut bad=g.clone();bad.mystic_history[0].bonuses.clear();assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());}
#[test]
fn mswm02_definition_and_paid_frame_corruption_rejected(){let d=m::definition();for case in 0..3{let mut bad=d.clone();match case{0=>bad.abilities[0].once_per_game=false,1=>bad.abilities[1].costs.clear(),_=>bad.abilities[0].modes[0].targets[0].zone=Zone::Board};assert!(m::validate_definition(m::ID,&bad).is_err());}let mut g=setup();let a=clear(&g,0,"exposure");act(&mut g,0,a);for case in 0..3{let mut bad=g.clone();let f=bad.stack.last_mut().unwrap().frame.as_mut().unwrap();match case{0=>f.already_paid.clear(),1=>f.source.card.definition="MSJC09".into(),_=>{bad.players[0].society_zone.used_once_per_game.clear();}}assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());let mut room=crate::jc029_tests::envelope(&g);room.game=bad;assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&room).unwrap()).is_err());}}
#[test]
fn mswm02_natural_construct_asset_discard_contest_reward_then_once_clear_room_chain(){
 use crate::{deck,abi112_review_play_tests::Trace};
 let mut d=deck::preset("watchers").unwrap();d.id="closed-psc".into();d.name="公众安全委员会封闭自然测试".into();d.description="现有47张JC125加3张WM041；非官方预组".into();d.society_id=Some(m::ID.into());d.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:47},catalog::DeckEntry{card_id:"WM041".into(),count:3}];
 assert!(deck::validate(d.clone()).is_err());let mut societies=catalog::catalog().societies.clone();societies.iter_mut().find(|s|s.card.id==m::ID).unwrap().card.supported=true;let d=deck::validate_with_registry(d,&catalog::catalog().cards,&societies).unwrap();
 let mut other=d.clone();other.society_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();
 let mut selected=None;for seed in 1..65{let mut g=Game::new("psc-natural".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for seat in 1..4{g.join(format!("P{seat}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d.clone(),other.clone(),other.clone(),other.clone()]).unwrap();g.drive().unwrap();if g.players[0].hand.iter().any(|c|c.definition=="WM041"){selected=Some((seed,g));break;}}
 let(seed,g)=selected.expect("bounded real seed for media in initial six");let mut t=Trace::new_preserving_rng(g,"mswm02-natural-contest-then-clear".into(),640);let mut invoked=false;let mut cleared=false;let mut completed=false;
 for _ in 0..700{
  if let Some(p)=t.room.game.pending.clone(){let ids=if p.choice.kind==crate::mystic_contest::REWARD_KIND{vec!["secrecy".into()]}else{let mut ids=p.choice.options.iter().map(|o|o.id.clone()).collect::<Vec<_>>();ids.sort_by_key(|id|t.room.game.players[p.seat].hand.iter().find(|c|c.id==*id).map_or(false,|c|c.definition=="WM041"));ids.truncate(p.choice.min.unwrap_or(0));ids};t.choose(ids);continue;}
  if cleared&&t.room.game.stack.is_empty(){assert_eq!(t.room.game.players[0].society_zone.secrecy,0);completed=true;break;}
  let g=&t.room.game;let legal=g.legal_actions(0);let mut a=None;
  if g.players[0].assets.len()<2{a=legal.iter().find(|a|a.action.kind=="asset"&&g.players[0].hand.iter().any(|c|c.definition=="JC125"&&Some(&c.id)==a.action.card_id.as_ref())).map(|a|a.action.clone());}
  if a.is_none()&&!invoked{a=legal.iter().find(|a|a.action.ability_id.as_deref()==Some(m::CONTEST)).map(|a|a.action.clone());if a.is_some(){invoked=true;}}
  if a.is_none()&&invoked&&g.mystic_contest.is_none()&&g.stack.is_empty()&&g.players[0].society_zone.secrecy>0{a=legal.iter().find(|a|a.action.ability_id.as_deref()==Some(m::CLEAR)&&a.action.option.as_deref()==Some("secrecy")&&a.action.target_id.as_deref()==Some("society:p0")).map(|a|a.action.clone());if a.is_some(){cleared=true;}}
  if let Some(a)=a{t.action(0,a);}else{t.pass();}
 }
 assert!(invoked&&cleared&&completed,"natural chain at turn {}",t.room.game.turn);assert!(t.room.game.players[0].society_zone.used_once_per_game.contains(m::CLEAR));
 let mut value=t.value();for step in value["steps"].as_array_mut().unwrap(){let room=crate::room::RoomEnvelope::from_persisted(step["expected"]["state"].as_str().unwrap()).unwrap();let cmd=serde_json::from_value(step["command"].clone()).unwrap();let dup=room.transition(step["seat"].as_u64().unwrap()as usize,Some(cmd),0).unwrap();assert_eq!(dup.outcome,"rejected");assert!(!dup.changed&&dup.journal.is_empty());assert_eq!(dup.state,step["expected"]["state"]);step["duplicate"]=serde_json::to_value(dup).unwrap();}
 value["construction"]=serde_json::json!({"deck":d,"seed":seed,"admission":"private candidate registry only","noLayoutOrResourceMutation":true});
 if let Ok(path)=std::env::var("MSWM02_NATIVE_OUT"){std::fs::write(path,serde_json::to_vec_pretty(&serde_json::json!({"catalog":catalog::catalog(),"sourceBindings":source_bindings(),"cases":[value]})).unwrap()).unwrap();}
}
fn source_bindings()->serde_json::Value {use sha2::{Digest,Sha256};let mut b=crate::jc066_tests::source_bindings();for(name,bytes)in[("rust-game/src/mswm02.rs",include_bytes!("mswm02.rs").as_slice()),("rust-game/src/mswm02_tests.rs",include_bytes!("mswm02_tests.rs").as_slice()),("rust-game/src/mystic_hooks.rs",include_bytes!("mystic_hooks.rs").as_slice()),("rust-game/src/pack_a_contest.rs",include_bytes!("pack_a_contest.rs").as_slice()),("rust-game/src/society.rs",include_bytes!("society.rs").as_slice())]{b["files"].as_object_mut().unwrap().insert(name.into(),serde_json::json!(format!("{:x}",Sha256::digest(bytes))));}b}
#[test]
fn mswm02_clearing_absent_kind_preserves_other_kind_and_still_spends_once(){for (mode,exposure,secrecy) in [("secrecy",3,0),("exposure",0,4)]{let mut g=setup();g.players[2].society_zone.exposure=exposure;g.players[2].society_zone.secrecy=secrecy;let a=clear(&g,2,mode);act(&mut g,0,a);pass_top(&mut g);assert_eq!((g.players[2].society_zone.exposure,g.players[2].society_zone.secrecy),(exposure,secrecy));assert!(g.players[0].society_zone.used_once_per_game.contains(m::CLEAR));}}
#[test]
fn mswm02_forged_media_receipt_and_duplicate_cost_selection_reject(){let mut g=setup();let def=media();let id=held(&mut g,&def,0);let mut a=contest(&g,id.clone());a.cost_selected=Some(vec![id.clone(),id.clone()]);reject(&mut g,0,a);let a=contest(&g,id);act(&mut g,0,a);let mut bad=g.clone();if let PaidCost::MSWM02Discard{card,..}=&mut bad.stack.last_mut().unwrap().frame.as_mut().unwrap().already_paid[2]{card.definition="JC125".into();}assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());}
